import 'package:flutter/material.dart';
import 'package:zen_core/zen_core.dart';
import 'package:zen_ui_widgets/zen_ui_widgets.dart';

import '../theme/identity_theme_extension.dart';

/// A reusable text field for Identity forms.
///
/// On Apple platforms this is a [ZenTextField], drawn Cupertino. Elsewhere it adapts to
/// [IdentityThemeExtension]: a filled field with the brand-colour border.
///
/// An [obscureText] field also gets a show/hide button beside it, so a password typed, pasted or
/// generated by a password manager can be checked before it is submitted. The button sits
/// outside the field's merged accessible node, so it is announced on its own rather than as part
/// of the input. Its wording is `zen_ui_widgets`' ("Show password" / "Hide password"), so the
/// application registers `zenWidgetsLocaleDelegate` beside `identityLocaleDelegate`.
class IdentityTextField extends StatefulWidget {
  final TextEditingController? controller;
  final String label;
  final String? hint;
  final String? errorText;
  final bool obscureText;
  final TextInputType? keyboardType;
  final Iterable<String>? autofillHints;
  final TextInputAction? textInputAction;
  final ValueChanged<String>? onFieldSubmitted;
  final FormFieldValidator<String>? validator;
  final bool enabled;

  const IdentityTextField({
    super.key,
    required this.label,
    this.controller,
    this.hint,
    this.errorText,
    this.obscureText = false,
    this.keyboardType,
    this.autofillHints,
    this.textInputAction,
    this.onFieldSubmitted,
    this.validator,
    this.enabled = true,
  });

  @override
  State<IdentityTextField> createState() => _IdentityTextFieldState();
}

// Centres the 48-pixel button on the 54-pixel input box it sits over, and the room the box keeps
// at its right edge so typed text never runs under the button.
const double _toggleTop = 3;
const double _toggleInset = zenIconButtonSize;

class _IdentityTextFieldState extends State<IdentityTextField> {
  bool _revealed = false;

  /// [field] with the reveal button beside it, or [field] alone when the text is not hidden.
  Widget _withToggle(BuildContext context, Widget field, double top) {
    if (!widget.obscureText) return field;
    final messages = ZenWidgetsLocalizations.of(context);
    // Laid over the field's right edge rather than beside it, so the box keeps the width of the
    // other fields. The button is outside the field's merged node; the field makes room for it
    // with [_toggleInset].
    return Stack(
      children: [
        field,
        Positioned(
          top: top,
          right: 0,
          child: ZenIconButton(
            icon: _revealed ? Icons.visibility_off : Icons.visibility,
            label: _revealed ? messages.hidePassword : messages.showPassword,
            onPressed: widget.enabled ? () => setState(() => _revealed = !_revealed) : null,
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final label = widget.label;
    final obscured = widget.obscureText && !_revealed;
    if (zenIsApplePlatform) {
      return ZenTextField(
        label: label,
        controller: widget.controller,
        hint: widget.hint,
        errorText: widget.errorText,
        obscureText: widget.obscureText,
        revealable: widget.obscureText,
        keyboardType: widget.keyboardType,
        autofillHints: widget.autofillHints,
        textInputAction: widget.textInputAction,
        onSubmitted: widget.onFieldSubmitted,
        validator: widget.validator,
        enabled: widget.enabled,
      );
    }

    // Access custom theme
    final theme =
        Theme.of(context).extension<IdentityThemeExtension>() ?? IdentityThemeExtension.fallback();

    final borderSide = BorderSide(color: theme.brandColor.withValues(alpha: 0.5));
    final errorBorderSide = BorderSide(color: theme.errorColor);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        ExcludeSemantics(
          child: Text(
            label,
            style: theme.subtitleStyle.copyWith(
              fontWeight: FontWeight.w600,
              color: Theme.of(context).colorScheme.onSurface,
            ),
          ),
        ),
        SizedBox(height: theme.spacing / 2),
        // Merged into the field's own node. Left as a separate Semantics, the label sat on a node
        // a screen reader never focuses, and the focusable field was named by its hint alone —
        // "you@example.com, text field", with no word of what the field is for.
        _withToggle(
          context,
          MergeSemantics(
            child: Semantics(
              label: label,
              child: TextFormField(
                controller: widget.controller,
                obscureText: obscured,
                keyboardType: widget.keyboardType,
                autofillHints: widget.autofillHints,
                textInputAction: widget.textInputAction,
                onFieldSubmitted: widget.onFieldSubmitted,
                validator: widget.validator,
                enabled: widget.enabled,
                style: theme.subtitleStyle.copyWith(color: Theme.of(context).colorScheme.onSurface),
                decoration: InputDecoration(
                  hintText: widget.hint,
                  errorText: widget.errorText,
                  filled: true,
                  fillColor: theme.surfaceColor,
                  contentPadding: EdgeInsetsDirectional.only(
                    start: theme.spacing,
                    end: theme.spacing + (widget.obscureText ? _toggleInset : 0),
                    top: theme.spacing,
                    bottom: theme.spacing,
                  ),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: borderSide,
                  ),
                  enabledBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: borderSide,
                  ),
                  focusedBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: borderSide.copyWith(width: 2, color: theme.brandColor),
                  ),
                  errorBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: errorBorderSide,
                  ),
                  focusedErrorBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: errorBorderSide.copyWith(width: 2),
                  ),
                ),
              ),
            ),
          ),
          _toggleTop,
        ),
      ],
    );
  }
}
